(function () {
  var d = (dec && dec.data) ? dec.data : {};
  var sid = String(d.submission_id || '');
  return {
    submission_id: sid,
    // A decision with no submission_id cannot be routed to anyone. Failing the
    // run is the right failure for that: it is a malformed decision, not a
    // transient condition, and both flow 1 and flow 2 do set it.
    ok: sid !== ''
  };
})();

(function () {
  var d = (dec && dec.data) ? dec.data : {};
  var s = (sub && sub.data) ? sub.data : {};
  // The submission wins for both fields: it is written once by the ingress and
  // never updated, whereas a decision may be written by any of three flows and
  // only one of them stamps them.
  var acct = String(s.distributor_account_id || d.distributor_account_id || '');
  var ver = Number(s.version || d.submission_version || 0);
  var row = (dists && dists[acct]) ? dists[acct] : null;

  // BOUND before ISSUED: quote-bind writes outcome BOUND with decision_status
  // ISSUED, so reading decision_status first reports a bound policy as merely
  // issued.
  var status = String(d.outcome) === 'BOUND' ? 'BOUND'
             : String(d.outcome) === 'SANCTION_REFERRAL' ? 'SANCTION_REFERRAL'
             : String(d.decision_status) === 'ISSUED' ? 'ISSUED'
             : String(d.decision_status) === 'DECLINED' ? 'DECLINED'
             : String(d.outcome) === 'DECLINE' ? 'DECLINED'
             : 'REFERRED';

  // The projection carries the OUTCOME, never the answers: the distributor
  // already holds the answers, because they are the broker's.
  var projection = {
    quote_id: String(d.quote_id || s.quote_id || ''),
    submission_version: ver,
    quote_reference: String(d.quote_reference || s.quote_reference || ''),
    // quote_outcome_config.outcome enumerates ACCEPT/REFER/DECLINE ONLY, while
    // decision_config.outcome also enumerates BOUND and SANCTION_REFERRAL.
    // Sending the decision's value straight across 400s the outcome write on
    // every bind -- the two enums are a field-authority mismatch across the
    // crossing. The lifecycle value belongs in outcome_status, which does
    // enumerate BOUND; outcome stays the underwriting verdict it always was.
    outcome: (String(d.outcome) === 'DECLINE' ? 'DECLINE'
            : String(d.outcome) === 'REFER' ? 'REFER'
            : 'ACCEPT'),
    outcome_status: status,
    product_code: String(d.product_code || ''),
    product_version: String(d.product_version || s.product_version || ''),
    decision_seq: Number(d.decision_seq || 0),
    decided_at: String(d.decided_at || ''),
    total_payable: Number(d.total_payable || 0),
    premium_breakdown: {
      base_premium: Number(d.base_premium || 0),
      broker_commission: Number(d.broker_commission || 0),
      fsl_levy: Number(d.fsl_levy || 0),
      gst: Number(d.gst || 0),
      stamp_duty: Number(d.stamp_duty || 0),
      premium_basis: String(d.premium_basis || '')
    },
    reasons: Array.isArray(d.broker_reasons) ? d.broker_reasons : [],
    documents: Array.isArray(d.issued_document_refs) ? d.issued_document_refs : [],
    quote_validity_expiry: String(d.quote_validity_expiry || ''),
    policy_number: String(d.policy_number || ''),
    bound_at: String(d.bound_at || '')
  };

  return {
    deliverable: row !== null && projection.quote_id !== '' && ver > 0,
    reason: row === null ? ('no distributor registered for account "' + acct + '"')
          : (projection.quote_id === '' ? 'neither the decision nor its submission carries a quote_id'
          : (ver > 0 ? '' : 'neither the decision nor its submission carries a submission version')),
    distributor_account_id: acct,
    endpoint: row ? String(row.decision_url || '') : '',
    projection: projection
  };
})();
